-- Bangles by Beauty - single-file Supabase deploy script.
--
-- Generated by scripts/generate-deploy.mjs - do not edit by hand.
-- Concatenates supabase/migrations/*.sql in order, then supabase/seed.sql.
--
-- Run this once in the Supabase SQL editor (or psql) to provision the schema,
-- security policies and seed catalogue data. Every statement is idempotent, so
-- re-running it is safe.

-- 0001_extensions_and_types.sql
-- Extensions and shared enums for the Bangles by Beauty schema.
--
-- `gen_random_uuid()` is provided by pgcrypto on older Postgres versions;
-- Supabase ships it by default, but the extension is created here so the
-- migration also works on a vanilla Postgres 13+ instance.

create extension if not exists pgcrypto with schema extensions;
create extension if not exists "uuid-ossp" with schema extensions;

do $$
begin
  if not exists (select 1 from pg_type where typname = 'profile_role') then
    create type public.profile_role as enum ('customer', 'admin');
  end if;
  if not exists (select 1 from pg_type where typname = 'order_status') then
    create type public.order_status as enum (
      'pending', 'confirmed', 'processing', 'dispatched', 'delivered', 'cancelled'
    );
  end if;
end $$;

-- Shared trigger to keep `updated_at` current. Every mutable table reuses it.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$$;

-- 0002_profiles_and_settings.sql
-- Admin/customer profiles linked to Supabase Auth, and the key/value settings
-- store the storefront reads at runtime.

create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text,
  role public.profile_role not null default 'customer',
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

comment on table public.profiles is
  'One row per authenticated user. Role lives here (never in client metadata) and is the sole source of admin authorisation.';

drop trigger if exists trg_profiles_updated_at on public.profiles;
create trigger trg_profiles_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- Create a profile automatically whenever a user signs up.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email, '@', 1)))
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Storefront settings are stored one key per row so the admin UI can patch
-- individual values without rewriting a blob.
create table if not exists public.store_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default timezone('utc', now())
);

comment on table public.store_settings is
  'Editable storefront settings (announcement, contact links, delivery copy). Values are stored per key and merged over defaults at read time.';

drop trigger if exists trg_store_settings_updated_at on public.store_settings;
create trigger trg_store_settings_updated_at
  before update on public.store_settings
  for each row execute function public.set_updated_at();

-- 0003_catalog_tables.sql
-- Catalogue tables: categories, products, product images and optional variants.
--
-- Notes on legacy data:
--   * `stock_quantity = null` means inventory is untracked (made to order).
--     The legacy site never published stock numbers, so none are invented.
--   * `compare_at_price` is null for every migrated product because the
--     original catalogue had no discounts.
--   * `legacy_id` / `legacy_image_source` retain provenance from the audit so
--     migrated rows can be traced back to the source site.

create table if not exists public.categories (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  description text,
  image_url text,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

drop trigger if exists trg_categories_updated_at on public.categories;
create trigger trg_categories_updated_at
  before update on public.categories
  for each row execute function public.set_updated_at();

create table if not exists public.products (
  id uuid primary key default gen_random_uuid(),
  category_id uuid references public.categories (id) on delete set null,
  name text not null,
  slug text not null unique,
  description text not null default '',
  sku text,
  price numeric(10, 2) not null default 0 check (price >= 0),
  compare_at_price numeric(10, 2) check (compare_at_price is null or compare_at_price >= 0),
  stock_quantity integer check (stock_quantity is null or stock_quantity >= 0),
  primary_image_url text,
  colours text[] not null default '{}',
  is_active boolean not null default true,
  is_featured boolean not null default false,
  is_new_arrival boolean not null default false,
  seo_title text,
  seo_description text,
  legacy_id text,
  legacy_image_source text,
  sort_index integer not null default 0,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

comment on column public.products.stock_quantity is
  'Null means untracked / made to order. A number is an explicit count set by an admin.';

create index if not exists products_category_id_idx on public.products (category_id);
create index if not exists products_is_active_idx on public.products (is_active);
create index if not exists products_is_featured_idx on public.products (is_featured) where is_featured;
create index if not exists products_is_new_arrival_idx on public.products (is_new_arrival) where is_new_arrival;
create index if not exists products_price_idx on public.products (price);
create index if not exists products_created_at_idx on public.products (created_at desc);
create index if not exists products_colours_idx on public.products using gin (colours);
create index if not exists products_search_idx on public.products
  using gin (to_tsvector('simple', coalesce(name, '') || ' ' || coalesce(description, '') || ' ' || coalesce(sku, '')));

drop trigger if exists trg_products_updated_at on public.products;
create trigger trg_products_updated_at
  before update on public.products
  for each row execute function public.set_updated_at();

create table if not exists public.product_images (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  image_url text not null,
  storage_path text,
  alt_text text not null default '',
  sort_order integer not null default 0,
  created_at timestamptz not null default timezone('utc', now())
);

create index if not exists product_images_product_id_idx on public.product_images (product_id, sort_order);

create table if not exists public.product_variants (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  variant_name text not null,
  variant_value text not null,
  sku text,
  price_override numeric(10, 2) check (price_override is null or price_override >= 0),
  stock_quantity integer check (stock_quantity is null or stock_quantity >= 0),
  is_active boolean not null default true,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create index if not exists product_variants_product_id_idx on public.product_variants (product_id);

drop trigger if exists trg_product_variants_updated_at on public.product_variants;
create trigger trg_product_variants_updated_at
  before update on public.product_variants
  for each row execute function public.set_updated_at();

-- 0004_orders.sql
-- Enquiry/order records.
--
-- The storefront does not take payment: customers send their selection to the
-- studio over WhatsApp. These tables let an admin keep a written record of
-- enquiries that were agreed, without ever claiming a payment happened online.
-- Line items snapshot the product name, variant and unit price at the time the
-- order was recorded so later catalogue edits do not rewrite history.

create sequence if not exists public.order_number_seq start 1001;

create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique default ('BB-' || to_char(timezone('utc', now()), 'YYMM') || '-' || lpad(nextval('public.order_number_seq')::text, 5, '0')),
  customer_name text,
  customer_phone text,
  status public.order_status not null default 'pending',
  currency text not null default 'INR',
  subtotal numeric(12, 2) not null default 0 check (subtotal >= 0),
  total_amount numeric(12, 2) not null default 0 check (total_amount >= 0),
  notes text,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create index if not exists orders_status_idx on public.orders (status);
create index if not exists orders_created_at_idx on public.orders (created_at desc);

drop trigger if exists trg_orders_updated_at on public.orders;
create trigger trg_orders_updated_at
  before update on public.orders
  for each row execute function public.set_updated_at();

create table if not exists public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  product_id uuid references public.products (id) on delete set null,
  product_name_snapshot text not null,
  selected_variant_snapshot text,
  quantity integer not null default 1 check (quantity > 0),
  unit_price numeric(10, 2) not null default 0 check (unit_price >= 0),
  line_total numeric(12, 2) not null default 0 check (line_total >= 0)
);

create index if not exists order_items_order_id_idx on public.order_items (order_id);
create index if not exists order_items_product_id_idx on public.order_items (product_id);

comment on table public.order_items is
  'Snapshot of what was agreed. `product_id` may become null if a product is deleted, but the snapshot columns preserve the historical record.';

-- 0005_rls_policies.sql
-- Row Level Security.
--
-- Model:
--   * The storefront reads with the anon key: it can see active categories and
--     products, their images/variants, and the settings blob.
--   * Authenticated admins (profiles.role = 'admin') get full access.
--   * Orders are private to admins.
--
-- `public.is_admin()` is SECURITY DEFINER so a policy on `profiles` can consult
-- the caller's own role without recursing through the policy it is evaluating.

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.profiles
    where id = auth.uid()
      and role = 'admin'
  );
$$;

revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated;

-- A user must never be able to promote themselves. Only an existing admin may
-- change a role; otherwise the column is pinned to its previous value.
create or replace function public.guard_profile_role()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.role is distinct from old.role and not public.is_admin() then
    new.role := old.role;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_profiles_guard_role on public.profiles;
create trigger trg_profiles_guard_role
  before update on public.profiles
  for each row execute function public.guard_profile_role();

-- ---------------------------------------------------------------------------
-- Enable RLS
-- ---------------------------------------------------------------------------
alter table public.profiles          enable row level security;
alter table public.store_settings    enable row level security;
alter table public.categories        enable row level security;
alter table public.products          enable row level security;
alter table public.product_images    enable row level security;
alter table public.product_variants  enable row level security;
alter table public.orders            enable row level security;
alter table public.order_items       enable row level security;

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
drop policy if exists profiles_select_own_or_admin on public.profiles;
create policy profiles_select_own_or_admin on public.profiles
  for select using (auth.uid() = id or public.is_admin());

drop policy if exists profiles_update_own_or_admin on public.profiles;
create policy profiles_update_own_or_admin on public.profiles
  for update using (auth.uid() = id or public.is_admin())
  with check (auth.uid() = id or public.is_admin());

drop policy if exists profiles_admin_all on public.profiles;
create policy profiles_admin_all on public.profiles
  for all using (public.is_admin())
  with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- store_settings (public read, admin write)
-- ---------------------------------------------------------------------------
drop policy if exists store_settings_public_read on public.store_settings;
create policy store_settings_public_read on public.store_settings
  for select using (true);

drop policy if exists store_settings_admin_write on public.store_settings;
create policy store_settings_admin_write on public.store_settings
  for all using (public.is_admin())
  with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- categories (active rows public, admin sees all)
-- ---------------------------------------------------------------------------
drop policy if exists categories_public_read on public.categories;
create policy categories_public_read on public.categories
  for select using (is_active or public.is_admin());

drop policy if exists categories_admin_write on public.categories;
create policy categories_admin_write on public.categories
  for all using (public.is_admin())
  with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- products
-- ---------------------------------------------------------------------------
drop policy if exists products_public_read on public.products;
create policy products_public_read on public.products
  for select using (is_active or public.is_admin());

drop policy if exists products_admin_write on public.products;
create policy products_admin_write on public.products
  for all using (public.is_admin())
  with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- product_images / product_variants (visible when their product is visible)
-- ---------------------------------------------------------------------------
drop policy if exists product_images_read on public.product_images;
create policy product_images_read on public.product_images
  for select using (
    exists (
      select 1 from public.products p
      where p.id = product_id and (p.is_active or public.is_admin())
    )
  );

drop policy if exists product_images_admin_write on public.product_images;
create policy product_images_admin_write on public.product_images
  for all using (public.is_admin())
  with check (public.is_admin());

drop policy if exists product_variants_read on public.product_variants;
create policy product_variants_read on public.product_variants
  for select using (
    (is_active and exists (
      select 1 from public.products p
      where p.id = product_id and (p.is_active or public.is_admin())
    ))
    or public.is_admin()
  );

drop policy if exists product_variants_admin_write on public.product_variants;
create policy product_variants_admin_write on public.product_variants
  for all using (public.is_admin())
  with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- orders / order_items (admins only)
-- ---------------------------------------------------------------------------
drop policy if exists orders_admin_all on public.orders;
create policy orders_admin_all on public.orders
  for all using (public.is_admin())
  with check (public.is_admin());

drop policy if exists order_items_admin_all on public.order_items;
create policy order_items_admin_all on public.order_items
  for all using (public.is_admin())
  with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------
grant usage on schema public to anon, authenticated;

grant select on public.categories, public.products, public.product_images,
  public.product_variants, public.store_settings to anon, authenticated;

grant select, insert, update, delete on public.profiles to authenticated;
grant select, insert, update, delete on public.categories, public.products,
  public.product_images, public.product_variants, public.store_settings,
  public.orders, public.order_items to authenticated;

grant usage, select on sequence public.order_number_seq to authenticated;

-- 0006_storage.sql
-- Storage bucket for product photography.
--
-- The bucket is public-read (product photos are shown to everyone) but only
-- admins may upload, replace or delete files. Files are stored under a folder
-- named after the product id, e.g. `product-images/<product_id>/<file>.webp`.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'product-images',
  'product-images',
  true,
  5242880, -- 5 MB per file
  array['image/jpeg', 'image/png', 'image/webp', 'image/avif']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Anyone may read product images.
drop policy if exists product_images_public_read on storage.objects;
create policy product_images_public_read on storage.objects
  for select using (bucket_id = 'product-images');

-- Only admins may write.
drop policy if exists product_images_admin_insert on storage.objects;
create policy product_images_admin_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'product-images' and public.is_admin());

drop policy if exists product_images_admin_update on storage.objects;
create policy product_images_admin_update on storage.objects
  for update to authenticated
  using (bucket_id = 'product-images' and public.is_admin())
  with check (bucket_id = 'product-images' and public.is_admin());

drop policy if exists product_images_admin_delete on storage.objects;
create policy product_images_admin_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'product-images' and public.is_admin());

-- 0007_product_colour_images.sql
-- Per-colour product photography.
--
-- Some products (currently the glass bangles) are sold in several colours and
-- have a distinct photo for each one. `colour_images` stores that mapping as
-- an ordered JSON array of { "colour": string, "image_url": string } objects so
-- the storefront can swap the gallery image when a colour is selected.
--
-- Kept alongside the existing `colours text[]` column rather than replacing it:
-- `colours` drives filtering/search, while `colour_images` only carries media.

alter table public.products
  add column if not exists colour_images jsonb not null default '[]'::jsonb;

comment on column public.products.colour_images is
  'Ordered [{ colour, image_url }] media per colour. Empty array when a product has no per-colour photography.';

-- The admin settings form posts every key on each save, and supabase-js
-- serialises a JS `null` as SQL NULL. The original `value jsonb not null`
-- constraint rejected that with:
--   null value in column "value" of relation "store_settings"
--   violates not-null constraint
-- which made it impossible to save (or clear) optional settings such as
-- contact_email. JSON null and SQL NULL both read back as JS null through
-- PostgREST, so the constraint is simply dropped.
alter table public.store_settings
  alter column value drop not null;

-- Repair rows that were stored as the JSON *string* "null" while working
-- around the constraint; they should be JSON null instead.
update public.store_settings
set value = 'null'::jsonb
where value = '"null"'::jsonb;

-- 0009_razorpay_payments.sql
--
-- Extends the existing orders table for Razorpay-powered checkout and adds an
-- immutable payment-events log so payment status is driven only by verified
-- server-side events (Razorpay Checkout verification + webhooks).
--
-- Apply this to your Supabase project before enabling Razorpay checkout.
-- All monetary additions are stored in integer paise (₹1 = 100 paise).

-- ---------------------------------------------------------------------------
-- orders: payment + fulfilment detail
-- ---------------------------------------------------------------------------
alter table public.orders
  add column if not exists customer_email text,
  add column if not exists shipping_address text,
  add column if not exists shipping_fee_paise integer not null default 0 check (shipping_fee_paise >= 0),
  add column if not exists discount_paise integer not null default 0 check (discount_paise >= 0),
  add column if not exists payment_status text not null default 'pending'
    check (payment_status in ('pending','authorized','paid','failed','refunded','partially_refunded')),
  add column if not exists razorpay_order_id text unique,
  add column if not exists razorpay_payment_id text unique;

create index if not exists orders_razorpay_order_id_idx on public.orders (razorpay_order_id);
create index if not exists orders_razorpay_payment_id_idx on public.orders (razorpay_payment_id);
create index if not exists orders_payment_status_idx on public.orders (payment_status);

-- ---------------------------------------------------------------------------
-- payment_events: idempotent log of Razorpay webhook / verification events
-- ---------------------------------------------------------------------------
create table if not exists public.payment_events (
  id uuid primary key default gen_random_uuid(),
  provider text not null default 'razorpay' check (provider = 'razorpay'),
  event_id text not null unique,
  event_type text not null,
  internal_order_id uuid references public.orders (id) on delete set null,
  processing_status text not null default 'pending'
    check (processing_status in ('pending','processed','ignored')),
  created_at timestamptz not null default timezone('utc', now()),
  processed_at timestamptz
);

create index if not exists payment_events_event_id_idx on public.payment_events (event_id);
create index if not exists payment_events_order_idx on public.payment_events (internal_order_id);

-- payment_events is an append-only log, so it deliberately has no updated_at
-- column and no set_updated_at() trigger.

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.payment_events enable row level security;

drop policy if exists payment_events_admin_all on public.payment_events;
create policy payment_events_admin_all on public.payment_events
  for all using (public.is_admin())
  with check (public.is_admin());

grant select, insert, update, delete on public.payment_events to authenticated;

comment on table public.payment_events is
  'Deduplicated log of Razorpay payment events. process idempotently; never trust unverified events.';
comment on column public.orders.payment_status is
  'Authoritative payment state. Updated only after server-side Razorpay signature verification or a verified webhook.';
comment on column public.orders.razorpay_order_id is
  'Razorpay order id created server-side for this order.';
comment on column public.orders.razorpay_payment_id is
  'Razorpay payment id captured after successful verification.';

-- 0010_fix_payment_events_trigger.sql
--
-- Migration 0009 originally attached the shared `set_updated_at()` trigger to
-- `public.payment_events`. That trigger writes `new.updated_at`, but the
-- append-only `payment_events` table has no `updated_at` column, so any future
-- UPDATE on the table would fail with:
--   record "new" has no field "updated_at"
--
-- The event log is never updated (rows are inserted once and deduplicated by
-- `event_id`), so the trigger is removed entirely. This migration is idempotent
-- and safe to run whether or not 0009 has already been applied.

drop trigger if exists trg_payment_events_updated_at on public.payment_events;

